/** GeoJSON FeatureCollection for one suburb — what the map component consumes. */
export function boundaryGeoJson(slug: string, name?: string) {
  const b = SUBURB_BOUNDARIES[slug];
  if (!b) return null;
  return {
    type: 'FeatureCollection' as const,
    features: b.rings.map((ring) => ({
      type: 'Feature' as const,
      properties: { name: name ?? slug },
      geometry: { type: 'Polygon' as const, coordinates: [ring] },
    })),
  };
}
